			      mult_perc(fs_info->fs_devices->total_rw_bytes, 10));
	data_chunk_size = min_t(u64, data_chunk_size, SZ_1G);


	if (avail <= data_chunk_size)
		return 0;
	avail -= data_chunk_size;


	if (flush == BTRFS_RESERVE_FLUSH_ALL)
		avail >>= 3;
	else
		avail >>= 1;
	return avail;
}


